// @ts-nocheck -- route search types are generated by the embedded app.
//
// The activity ledger: one activity's definition (video/audio iframe, reading
// body, quiz body) with every employee-arranged row for it underneath — each
// participant keeps their own editable planned/actual hours. Content
// activities match across every group that shares the activity, attendance
// matches on the shared session key, and hand-typed assignments show only
// their own row.
import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import Swal from "sweetalert2";
import { Check, FileText, Pencil, X } from "lucide-react";
import { Table, TableBody, TableCell, TableHeader, TableRow } from "@/features/audit/learner-log-pro-copy/components/ui/table";
import { completionBadge } from "@/features/audit/learner-log-pro-copy/components/ManualActivityRow";
import {
  getActivityLedger,
  patchManualRow,
  type LedgerParticipant,
  type LedgerSourceParticipant,
} from "@/features/audit/learner-log-pro-copy/lib/manualApi";

export const Route = createFileRoute("/ledger")({
  validateSearch: (search: Record<string, unknown>) => ({
    ref: typeof search.ref === "string" ? search.ref : "",
    learner: typeof search.learner === "string" ? search.learner : "",
  }),
  component: LedgerPage,
});

function hours(value: number | null | undefined) {
  return value == null ? "—" : String(Math.round(value * 100) / 100);
}

function categoryBadgeClass(category: string) {
  switch ((category || "").toLowerCase()) {
    case "video": return "bg-primary/15 text-primary";
    case "audio": return "bg-[#673ab7]/15 text-[#673ab7]";
    case "reading+quiz": return "bg-success/15 text-success";
    case "attendance": return "bg-amber-500/15 text-amber-700";
    case "assignment": return "bg-[#182d48]/10 text-[#182d48]";
    default: return "bg-muted text-muted-foreground";
  }
}

// Shared quiz definitions store their questions as loosely-shaped JSON; show
// whatever fields exist without assuming a graded attempt.
function QuizDefinition({ quiz }: { quiz: { description: string | null; questions: unknown[] } }) {
  const questions = (quiz.questions ?? []).filter((item) => item && typeof item === "object") as Array<Record<string, unknown>>;
  return (
    <div className="space-y-3 px-5 py-4">
      {quiz.description ? <p className="text-sm leading-6 text-muted-foreground">{String(quiz.description)}</p> : null}
      {questions.map((question, index) => {
        const options = Array.isArray(question.options) ? question.options : [];
        return (
          <div key={String(question.question_id ?? index)} className="rounded-md border border-border bg-background/40 p-3">
            <p className="text-sm leading-6 text-foreground">
              <span className="mr-1.5 font-semibold text-muted-foreground">Q{String(question.question_order ?? index + 1)}.</span>
              {String(question.question_body ?? question.question_text ?? `Question ${index + 1}`)}
            </p>
            {options.length ? (
              <ul className="mt-2 space-y-1">
                {options.map((option: Record<string, unknown>, optionIndex: number) => (
                  <li key={optionIndex} className="flex items-start gap-2 rounded-sm px-2 py-1 text-sm text-muted-foreground">
                    <span className="mt-0.5 shrink-0 text-xs">•</span>
                    <span>{String(option?.option_body ?? option?.option_text ?? "")}</span>
                  </li>
                ))}
              </ul>
            ) : null}
          </div>
        );
      })}
      {!quiz.description && !questions.length ? (
        <p className="text-sm text-muted-foreground">This quiz has no stored definition body.</p>
      ) : null}
    </div>
  );
}

const SOURCE_STATUS_BADGES: Record<LedgerSourceParticipant["status"], { text: string; className: string }> = {
  attended: { text: "Attended", className: "bg-success/15 text-success" },
  absent: { text: "Absent", className: "bg-amber-500/15 text-amber-700" },
  completed: { text: "Completed", className: "bg-success/15 text-success" },
  not_completed: { text: "Not completed", className: "bg-amber-500/15 text-amber-700" },
  no_record: { text: "No record", className: "bg-muted text-muted-foreground" },
};

// Everyone the source says did (or missed) the activity, with a pointer to
// the monthly reports that already carry it.
function SourceParticipantsSection({ participants, category }: { participants: LedgerSourceParticipant[]; category: string }) {
  const isAttendance = (category || "").toLowerCase() === "attendance";
  const doneCount = participants.filter((item) => item.status === "attended" || item.status === "completed").length;
  return (
    <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
        <div>
          <h2 className="text-lg font-semibold text-[#182d48]">Learners who did this activity</h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {isAttendance
              ? "The whole register session — attended and absent — straight from the source"
              : "Every learner enrolled on this activity with their own LMS completion"}
          </p>
        </div>
        <div className="flex items-center gap-2 text-xs">
          <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono font-medium text-[#182d48]">{participants.length} learners</span>
          <span className="rounded-full bg-success/10 px-3 py-1.5 font-mono font-medium text-success">{doneCount} {isAttendance ? "attended" : "completed"}</span>
        </div>
      </header>
      <ul className="divide-y divide-border">
        {participants.map((participant, index) => {
          const badge = SOURCE_STATUS_BADGES[participant.status] ?? SOURCE_STATUS_BADGES.no_record;
          return (
            <li key={`${participant.aptem_id ?? "x"}-${index}`} className="flex flex-wrap items-center gap-3 px-7 py-2.5 odd:bg-[#f7f9fc]">
              <span className="min-w-48 text-sm font-medium text-foreground">
                {participant.aptem_id != null ? (
                  <Link to="/journal" search={{ learner: String(participant.aptem_id), period: participant.report_months[0] ?? "" } as never} className="hover:text-primary hover:underline">
                    {participant.learner_name}
                  </Link>
                ) : participant.learner_name}
              </span>
              <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${badge.className}`}>{badge.text}</span>
              <span className="flex-1" />
              {participant.on_report ? (
                <span className="flex flex-wrap items-center gap-1.5 text-[11px] text-muted-foreground">
                  On report:
                  {participant.report_months.map((month) => (
                    <Link key={month} to="/journal" search={{ learner: String(participant.aptem_id), period: month } as never} className="rounded-full bg-primary/10 px-2 py-0.5 font-semibold text-primary hover:underline">
                      {month}
                    </Link>
                  ))}
                </span>
              ) : (
                <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-semibold text-muted-foreground">Not on any report</span>
              )}
            </li>
          );
        })}
      </ul>
      {!participants.length ? (
        <p className="py-10 text-center text-sm text-muted-foreground">The source holds no learners for this activity.</p>
      ) : null}
    </section>
  );
}

function ParticipantRow({ participant, className = "" }: { participant: LedgerParticipant; className?: string }) {
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [planned, setPlanned] = useState(String(participant.planned_hours));
  const [actual, setActual] = useState(String(participant.actual_hours));

  async function save() {
    const plannedValue = Number(planned || 0);
    const actualValue = Number(actual || 0);
    if (![plannedValue, actualValue].every((value) => Number.isFinite(value) && value >= 0 && value <= 50)) {
      return void Swal.fire({ icon: "error", title: "Check the hours", text: "Planned and actual hours must be between 0 and 50." });
    }
    setSaving(true);
    try {
      await patchManualRow(participant.id, { planned_hours: plannedValue, actual_hours: actualValue });
      await queryClient.invalidateQueries({ queryKey: ["activity-ledger"] });
      await queryClient.invalidateQueries({ queryKey: ["manual-rows"] });
      await queryClient.invalidateQueries({ queryKey: ["manual-summary"] });
      setEditing(false);
    } catch (cause) {
      await Swal.fire({ icon: "error", title: "Update failed", text: cause instanceof Error ? cause.message : "Could not update the hours." });
    } finally {
      setSaving(false);
    }
  }

  return (
    <TableRow className={className}>
      <TableCell className="whitespace-nowrap pl-7 text-sm font-medium">
        <Link to="/journal" search={{ learner: String(participant.aptem_id), period: participant.month } as never} className="hover:text-primary hover:underline">
          {participant.learner_name}
        </Link>
      </TableCell>
      <TableCell className="whitespace-nowrap text-xs text-muted-foreground">{participant.month_label}</TableCell>
      <TableCell className="whitespace-nowrap font-mono text-xs text-muted-foreground">{participant.activity_date ?? "—"}</TableCell>
      <TableCell className="min-w-56 max-w-[28rem] text-sm">
        <span className="font-medium text-foreground">{participant.title}</span>
        <div className="mt-1 flex flex-wrap gap-1.5">{completionBadge(participant.completion_note)}</div>
        {participant.documents.length ? (
          <ul className="mt-1.5 space-y-0.5">
            {participant.documents.map((doc) => (
              <li key={doc.id} className="flex items-center gap-1.5 text-xs">
                <FileText className="h-3 w-3 shrink-0 text-muted-foreground" />
                {doc.download_url
                  ? <a href={doc.download_url} target="_blank" rel="noreferrer" className="truncate text-primary hover:underline" title={doc.display_name}>{doc.display_name}</a>
                  : <span className="truncate text-muted-foreground" title={doc.display_name}>{doc.display_name}</span>}
              </li>
            ))}
          </ul>
        ) : null}
      </TableCell>
      <TableCell className="whitespace-nowrap text-center font-mono text-xs text-muted-foreground">{participant.timestamp_label || "—"}</TableCell>
      {editing ? (
        <>
          <TableCell><input type="number" min="0" max="50" step="0.01" value={planned} onChange={(event) => setPlanned(event.target.value)} className="h-8 w-20 rounded-md border border-border bg-card px-2 text-right font-mono text-xs outline-none focus:border-primary" /></TableCell>
          <TableCell><input type="number" min="0" max="50" step="0.01" value={actual} onChange={(event) => setActual(event.target.value)} className="h-8 w-20 rounded-md border border-border bg-card px-2 text-right font-mono text-xs outline-none focus:border-primary" /></TableCell>
        </>
      ) : (
        <>
          <TableCell className="text-right font-mono text-sm">{hours(participant.planned_hours)}</TableCell>
          <TableCell className="text-right font-mono text-sm text-success">{hours(participant.actual_hours)}</TableCell>
        </>
      )}
      <TableCell className="pr-7 text-right">
        <div className="flex justify-end gap-1">
          {editing ? (
            <>
              <button type="button" onClick={save} disabled={saving} className="rounded-md bg-primary p-1.5 text-primary-foreground disabled:opacity-50" title="Save hours" aria-label="Save hours"><Check className="h-3.5 w-3.5" /></button>
              <button type="button" onClick={() => { setPlanned(String(participant.planned_hours)); setActual(String(participant.actual_hours)); setEditing(false); }} disabled={saving} className="rounded-md border border-border p-1.5 hover:bg-secondary disabled:opacity-50" title="Cancel" aria-label="Cancel editing"><X className="h-3.5 w-3.5" /></button>
            </>
          ) : (
            <button type="button" onClick={() => setEditing(true)} className="rounded-md border border-border p-1.5 hover:bg-secondary" title="Edit hours" aria-label="Edit hours"><Pencil className="h-3.5 w-3.5" /></button>
          )}
        </div>
      </TableCell>
    </TableRow>
  );
}

function LedgerPage() {
  const router = useRouter();
  const { ref, learner } = Route.useSearch();

  const ledger = useQuery({
    queryKey: ["activity-ledger", ref],
    queryFn: () => getActivityLedger(ref),
    enabled: Boolean(ref),
  });

  const activity = ledger.data?.activity;
  const participants = ledger.data?.participants ?? [];
  const sourceParticipants = ledger.data?.source_participants ?? [];
  const plannedTotal = participants.reduce((sum, item) => sum + item.planned_hours, 0);
  const actualTotal = participants.reduce((sum, item) => sum + item.actual_hours, 0);
  const isMedia = ["video", "audio"].includes((ledger.data?.category ?? "").toLowerCase());

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="flex w-full flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Activity ledger</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/journal" search={{ learner } as never} className="font-medium hover:underline">Journal</Link>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1500px] space-y-6 px-6 py-8">
        {!ref ? (
          <p className="py-10 text-center text-sm text-muted-foreground">No activity reference was provided.</p>
        ) : ledger.isLoading ? (
          <p className="py-10 text-center text-sm text-muted-foreground">Loading activity ledger…</p>
        ) : ledger.isError ? (
          <p className="py-10 text-center text-sm text-destructive">{ledger.error instanceof Error ? ledger.error.message : "Could not load the activity ledger."}</p>
        ) : activity ? (
          <>
            <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
              <div className="h-1 bg-[#182d48]" />
              <div className="flex flex-wrap items-start justify-between gap-4 px-7 py-6">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className={`rounded-sm px-2 py-0.5 text-[10px] font-semibold uppercase ${categoryBadgeClass(ledger.data.category)}`}>{ledger.data.category}</span>
                    {activity.activity_date ? <span className="font-mono text-xs text-muted-foreground">{activity.activity_date}</span> : null}
                    {activity.module ? <span className="text-xs text-muted-foreground">{activity.module}</span> : null}
                  </div>
                  <h1 className="mt-2 text-2xl font-semibold tracking-tight text-[#182d48]">{activity.title}</h1>
                </div>
                {activity.configured_duration_minutes ? (
                  <div className="rounded-xl bg-[#f6f8fb] px-6 py-3 text-center">
                    <p className="text-[9px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Configured duration</p>
                    <p className="mt-1 font-mono text-sm font-semibold text-[#182d48]">{activity.configured_duration_minutes} min</p>
                  </div>
                ) : null}
              </div>

              {activity.content_url ? (
                <div className="border-t border-border">
                  <div className="flex items-center justify-between px-7 py-3">
                    <p className="label-caps">{isMedia ? "Activity media" : "Activity content"}</p>
                    <a href={activity.content_url} target="_blank" rel="noreferrer" className="text-xs font-medium text-primary hover:underline">Open in new tab ↗</a>
                  </div>
                  <div className="h-[520px] bg-black/5">
                    <iframe src={activity.content_url} title={activity.title} className="h-full w-full" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen />
                  </div>
                </div>
              ) : null}

              {activity.reading_text_body ? (
                <div className="border-t border-border">
                  <p className="label-caps px-7 py-3">Reading body</p>
                  <div className="max-h-[420px] overflow-y-auto whitespace-pre-wrap px-7 pb-6 text-sm leading-6 text-foreground">{activity.reading_text_body}</div>
                </div>
              ) : null}

              {activity.quiz ? (
                <div className="border-t border-border">
                  <div className="flex flex-wrap items-center gap-3 px-7 py-3">
                    <p className="label-caps">Quiz body</p>
                    {activity.quiz.maximum_score != null ? <span className="text-xs text-muted-foreground">Max score {activity.quiz.maximum_score}</span> : null}
                    {activity.quiz.passing_score != null ? <span className="text-xs text-muted-foreground">Pass mark {activity.quiz.passing_score}</span> : null}
                  </div>
                  <div className="px-2 pb-3"><QuizDefinition quiz={activity.quiz} /></div>
                </div>
              ) : null}
            </section>

            {sourceParticipants.length ? (
              <SourceParticipantsSection participants={sourceParticipants} category={ledger.data.category} />
            ) : null}

            <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
              <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
                <div>
                  <h2 className="text-lg font-semibold text-[#182d48]">Participating learners</h2>
                  <p className="mt-1 text-sm text-muted-foreground">Every learner whose monthly report includes this activity, with their own arranged hours</p>
                </div>
                <div className="flex items-center gap-2 text-xs">
                  <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono font-medium text-[#182d48]">{participants.length} learners</span>
                  <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono font-medium text-[#182d48]">planned {hours(plannedTotal)} h</span>
                  <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono font-medium text-[#182d48]">actual {hours(actualTotal)} h</span>
                </div>
              </header>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="border-0 bg-[#182d48] hover:bg-[#182d48]">
                      <th className="h-12 px-4 pl-7 text-left align-middle label-caps text-white">Learner</th>
                      <th className="h-12 px-4 text-left align-middle label-caps text-white">Report month</th>
                      <th className="h-12 px-4 text-left align-middle label-caps text-white">Date</th>
                      <th className="h-12 px-4 text-left align-middle label-caps text-white">Activity</th>
                      <th className="h-12 px-4 text-center align-middle label-caps text-white">Timestamp</th>
                      <th className="h-12 px-4 text-right align-middle label-caps text-white">Planned</th>
                      <th className="h-12 px-4 text-right align-middle label-caps text-white">Actual</th>
                      <th className="h-12 px-4 pr-7 text-right align-middle label-caps text-white">Actions</th>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {participants.map((participant) => (
                      <ParticipantRow key={participant.id} participant={participant} className="odd:bg-[#f7f9fc]" />
                    ))}
                  </TableBody>
                </Table>
                {!participants.length ? (
                  <p className="py-10 text-center text-sm text-muted-foreground">No employee-arranged rows reference this activity yet.</p>
                ) : null}
              </div>
            </section>
          </>
        ) : null}
      </main>
    </div>
  );
}
